<script setup>
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import { DataAnalysis, Timer, CircleCheck, Warning, Film } from '@element-plus/icons-vue';
import { api } from '../api/index.js';
import { usePolling } from '../components/polling.js';
import StatusTag from '../components/StatusTag.vue';
const data = ref(null), jobs = ref([]), error = ref(''), checks = ref({}), checking = ref(false), router = useRouter();
const metrics = [{ key: 'queued', label: '排队任务', hint: '等待开始的工作流', icon: Timer }, { key: 'running', label: '处理中', hint: '正在扫描或识别媒体', icon: DataAnalysis }, { key: 'completed', label: '已完成', hint: '当前进程内完成的任务', icon: CircleCheck }, { key: 'needs_review', label: '待确认', hint: '等待你选择匹配候选', icon: Warning }];
const names = { qbittorrent: 'qBittorrent', jellyfin: 'Jellyfin', deepseek: 'DeepSeek' };
async function load() { try { const [d, j] = await Promise.all([api('/dashboard', { quiet: true }), api('/workflows?pageSize=5', { quiet: true })]); data.value = d; jobs.value = j.items; error.value = ''; } catch (e) { error.value = e.message; } }
usePolling(load, 10000);
async function check() { checking.value = true; try { checks.value = await api('/connections/check', { method: 'POST' }); } catch {} finally { checking.value = false; } }
</script>
<template><el-alert v-if="error" :title="error" type="error" show-icon class="notice" :closable="false" /><div v-loading="!data && !error"><div class="metrics"><div v-for="m in metrics" :key="m.key" class="metric"><div class="metric-label">{{ m.label }}</div><div class="metric-icon"><el-icon><component :is="m.icon" /></el-icon></div><div class="metric-value">{{ data?.counts?.[m.key] || 0 }}</div><div class="metric-caption">{{ m.hint }}</div></div></div><section class="panel"><div class="panel-header"><h2>自动化处理流程</h2><span class="muted">下载完成通知驱动</span></div><div class="pipeline"><template v-for="(step, i) in [{ name: '下载完成', hint: 'qBittorrent 回调' }, { name: '扫描媒体库', hint: '等待 Jellyfin 完成' }, { name: '名称识别', hint: 'DeepSeek 提取信息' }, { name: '匹配与确认', hint: '应用后回读验证' }]" :key="i"><span v-if="i" class="pipeline-arrow">→</span><div class="pipeline-step"><span class="step-number">0{{ i + 1 }}</span><div><strong>{{ step.name }}</strong><small>{{ step.hint }}</small></div></div></template></div></section><div class="two-columns"><section class="panel"><div class="panel-header"><h2>服务连接</h2><el-button size="small" :loading="checking" @click="check">检查连接</el-button></div><div class="panel-body"><div v-for="(connection, key) in data?.connections" :key="key" class="connection-row"><div class="service-icon">{{ key === 'qbittorrent' ? 'qb' : key === 'jellyfin' ? 'J' : 'D' }}</div><div><strong>{{ names[key] }}</strong><span class="muted">{{ checks[key]?.ok ? '连接正常' : checks[key]?.error || (connection.configured ? '凭据已配置' : '尚未配置') }}</span></div><el-tag :type="checks[key]?.ok === false ? 'danger' : checks[key]?.ok ? 'success' : 'info'" round>{{ checks[key]?.ok === false ? '异常' : checks[key]?.ok ? '在线' : '未检查' }}</el-tag></div></div></section><section class="panel"><div class="panel-header"><h2>目标媒体库</h2><router-link to="/media" class="muted">前往识别 →</router-link></div><div class="panel-body"><div v-for="lib in data?.libraries" :key="lib.ItemId" class="library-row"><div class="service-icon"><el-icon><Film /></el-icon></div><div><h2>{{ lib.Name }}</h2><p>{{ lib.Locations?.join(', ') }}</p></div><span class="library-type">{{ lib.CollectionType === 'movies' ? '电影' : '电视剧' }}</span></div><div v-if="data && !data.libraries.length" class="empty-hint">暂无目标库，请检查连接配置。</div></div></section></div><section class="panel"><div class="panel-header"><h2>最近任务</h2><router-link to="/jobs" class="muted">查看全部 →</router-link></div><div class="table-wrap"><el-table :data="jobs" @row-click="row => router.push(`/jobs/${row.id}`)" style="cursor:pointer"><el-table-column label="任务" min-width="210"><template #default="{ row }">{{ row.input.hash ? `下载通知 · ${row.input.hash.slice(0, 12)}` : row.input.dryRun ? '候选预览' : '媒体扫描识别' }}</template></el-table-column><el-table-column prop="stage" label="当前阶段" min-width="180" /><el-table-column label="状态" width="110"><template #default="{ row }"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="创建时间" width="180"><template #default="{ row }">{{ new Date(row.createdAt).toLocaleString('zh-CN') }}</template></el-table-column><template #empty><div class="empty-hint">尚无任务，下载完成通知或手动扫描后将在这里显示。</div></template></el-table></div></section></div></template>
